#!/usr/bin/env python3
import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)


class Client:
    def __init__(self):
        self.token = None
        self.retries = {"rate_limited": 0, "unauthorized": 0, "other": 0}

    def _request_json(self, path, authenticated=True):
        while True:
            if authenticated and self.token is None:
                self.token = self._request_json("/token", authenticated=False)["token"]
            headers = {}
            if authenticated:
                headers["Authorization"] = f"Bearer {self.token}"
            request = urllib.request.Request(BASE + path, headers=headers,
                                             method="GET" if authenticated else "POST")
            try:
                with urllib.request.urlopen(request, timeout=30) as response:
                    return json.load(response)
            except urllib.error.HTTPError as exc:
                if exc.code == 401 and authenticated:
                    self.retries["unauthorized"] += 1
                    self.token = None
                    continue
                if exc.code == 429:
                    self.retries["rate_limited"] += 1
                    retry_after = exc.headers.get("Retry-After", "1")
                    try:
                        delay = float(retry_after)
                    except ValueError:
                        delay = 1.0
                    time.sleep(max(delay, 0.01))
                    continue
                if 500 <= exc.code < 600:
                    self.retries["other"] += 1
                    time.sleep(1)
                    continue
                raise
            except (TimeoutError, urllib.error.URLError):
                self.retries["other"] += 1
                time.sleep(1)

    def get(self, path):
        return self._request_json(path)


def parse_timestamp(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(timezone.utc)


client = Client()
seen = {}
duplicates = 0
duplicate_conflicts = []
qualifying = []
listing_count = 0

page_number = 1
expected_pages = None
while True:
    page = client.get(f"/orders?page={page_number}")
    if page["page"] != page_number:
        raise RuntimeError(f"requested page {page_number}, received {page['page']}")
    if expected_pages is None:
        expected_pages = page["total_pages"]
    elif page["total_pages"] != expected_pages:
        raise RuntimeError("total_pages changed during traversal")
    listing_count += len(page["items"])
    for order in page["items"]:
        order_id = order["id"]
        if order_id in seen:
            duplicates += 1
            if order != seen[order_id]:
                duplicate_conflicts.append(order_id)
            continue
        seen[order_id] = order
        placed_utc = parse_timestamp(order["placed_at"])
        if order["status"] == "shipped" and START <= placed_utc < END:
            qualifying.append(order)
    if page["next"] is None:
        if page_number != expected_pages:
            raise RuntimeError("pagination ended before total_pages")
        break
    expected_next = f"/orders?page={page_number + 1}"
    if page["next"] != expected_next:
        raise RuntimeError(f"unexpected next path: {page['next']}")
    page_number += 1

customers = {}
for customer_id in sorted({order["customer_id"] for order in qualifying}):
    customer = client.get(f"/customers/{customer_id}")
    if customer["id"] != customer_id:
        raise RuntimeError(f"customer mismatch for {customer_id}")
    customers[customer_id] = customer

by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
for order in qualifying:
    customer = customers[order["customer_id"]]
    discounted = (Decimal(order["amount_cents"]) *
                  (Decimal(100) - Decimal(customer["discount_pct"])) /
                  Decimal(100)).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    by_region[customer["region"]] += int(discounted)

result = {
    "total_cents": sum(by_region.values()),
    "order_count": len(qualifying),
    "duplicates_skipped": duplicates,
    "by_region": by_region,
}

audit = {
    "result": result,
    "pages": expected_pages,
    "listings": listing_count,
    "unique_orders": len(seen),
    "unique_qualifying_customers": len(customers),
    "duplicate_conflicts": duplicate_conflicts,
    "retries": client.retries,
}
print(json.dumps(audit, indent=2))
